struct Heavy { char big_data[100]; };
struct Light { int val; };

// 1. Runtime Polymorphism (RTP): Heap Indirection
// Base class needs VPtr. Payload lives on heap.
struct Base { virtual void run() = 0; };
struct Derived : Base { void run() override { /* ... */ } };

// 2. Compile-Time Polymorphism (CTP): Stack Storage
// Memory: max(sizeof(Heavy), sizeof(Light)) + Index byte
using PolyType = std::variant<Heavy, Light>;

void execute(PolyType& p) {
    // Dispatch mechanism: Internal index check (switch statement)
    std::visit([](auto& obj) {
        // Static dispatch: No V-table lookup overhead
        // Better cache locality due to stack storage
    }, p);
}
